public class Main {
	public static long smallestOdd(long[] a){
		long so = 0;
		for (int i = 0; i < a.length; i++) {
			if (a[i] % 2 == 1){
				so = a[i];
				break;
			}
		}
		if (so == 0)
			return 0;
		for (int i = 0; i < a.length; i++) {
			if (a[i] % 2 == 1 && so < a[i])
				so = a[i];
		}
		return so;
	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		long a[] = new long[n];
		for (int i = 0; i < a.length; i++) {
			a[i] = sc.nextLong();
