                if (n < 4) {
                        out.println(0);
                        return;
                }
                int a[] = new int[n];
                for (int i = 0; i < n - 3; i++) {
                        if (s[i] == 'b' && s[i + 1] == 'e' && s[i + 2] == 'a' && s[i + 3] == 'r') {
                                a[i] = 1;
                        }
                }
                long ans = 0;
                long right[] = new long[n];
                right[0] = a[0];
                for (int i = 1; i < n; i++) {
                        right[i] += right[i - 1] + a[i];
                }
                for (int i = 0; i < n; i++) {
                        for (int j = i; j < n - 3; j++) {
                                long t = 0;
                                if (i == 0) {
                                        t += right[j];
                                } else {
                                        t += right[j] - right[i - 1];
                                }
                                if (t > 0) {
                                        ans++;
                                }
                        }
                }
                out.println(ans);
        }

