    private static long calc(long val, long cap)
    {
        if (cap < 0) return 0;
        if (val > cap) return 0;
        if (val <= 0)
        {
            return tri(cap + 1) - calc(-val + 1, cap);
        }
        long v = cap - val + 1;
        long n = (v+1) / 2;
        return n * (2 * v + (n - 1) * -2) / 2;
