        int[] types = new int[n];
        for (int i = 0; i < n; i++) {
            types[i] = in.ni();
        }
        Arrays.sort(types);
        boolean ok = true;
        for (int i = 0; i < n - 1; i++) {
            int left = i + 1, right = n - 1;
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (types[i] < types[mid] && types[i] * 2 > types[mid]) {
                    ok = false;
                    break;
                } else {
                    right = mid - 1;
                }
            }
            if (!ok) break;
        }
        out.println(ok ? "NO" : "YES");
    }

