def max_ribbons(n, lengths):
    if 1 in lengths:
        return n

    unique = sorted(set(lengths))
    if unique[-1] == sum(unique) - unique[-1]:
        unique = unique[0:2]

    ribbons = [0] * (n + 1)

    for idx in unique:
        if idx <= n:
            ribbons[idx] = 1

    for i in range(unique[0] * 2, n + 1):
        prev_iterations = []
        for j in unique:
            if i >= j:
                prev_iterations.append(ribbons[i - j])
        if max(prev_iterations) > 0:
            ribbons[i] = 1 + max(prev_iterations)

    return ribbons[n]


