        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int[] a = new int[3];
            for (int i = 0; i < 3; ++i) {
                a[i] = in.nextInt();
            }
            int L = in.nextInt();
            int ans = 0;
            for (int i = 0; i <= L; ++i) {
                ans += (L - i + 1) * (L - i + 2) / 2;
            }

            for (int i = 0; i < 3; ++i) {
                for (int s = 0; s <= L; ++s) {
                    ans -= cnt(a[i], a[(i + 1) % 3], a[(i + 2) % 3], s);
                }
            }
            out.println(ans);
        }

        int cnt(int a, int b, int c, int s) {
            if (s + a < b + c) {
                return 0;
            }
            int cur = Math.min(s, (s + a - b - c) / 2);
            return (cur + 1) * (cur + 2) / 2;
        }

    }

