		}
		if (dp[i][currentRem] != -1) {
			return dp[i][currentRem];
		} else {
			if (currentRem == 1) {
				dp[i][currentRem] = arr[n - 1] - (i == 0 ? 0 : arr[i - 1]);
				return dp[i][currentRem];
			}
			if (currentRem > (n - i)) {
				return -1;
			} else {
				long max = -1;
				int j;
				long pre = -1;
				int h = i;
				for (j = i; j < n; j++) {
					long pp = maxRodCutting(arr, currentRem - 1, dp, j + 1, n);
					if (pp != -1) {
						max = Math.max(max, (arr[j] - (i == 0 ? 0 : arr[i - 1])) & pp);
						if (max != -pre) {
							h = j;
						}
					}
					pre = max;
				}

				dp[i][currentRem] = max;
				return max;

			}
		}
	}
}
