	public static void main (String[] args) throws NumberFormatException, IOException{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] limits = br.readLine().split(" ");
		int n = Integer.parseInt(limits[0]), k = Integer.parseInt(limits[1]);
		String[] strBills = br.readLine().split(" ");
		int[] bills = new int[n];
		for (int i = 0; i < n; i++){
			bills[i] = Integer.parseInt(strBills[i]);
		}
		int q = Integer.parseInt(br.readLine());
		int amt, count, bill;
		int[] used = new int[2];
		for (int i = 0; i<q; i++){
			amt = Integer.parseInt(br.readLine());
			count = 0;
			used[0] = 0;
			used[1] = 0;
			while (amt >= bills[0] && count < k){
				bill = nextBill(bills, amt);
				if (used[0] == 0 || used[0] == bill){ used[0] = bill; }
				else if (used[1] == 0 || used[1] == bill){ used[1] = bill; }
				else { break; }
				amt -= bill;
				count++;
			}
			if (amt == 0){ System.out.println(count); }
			else { System.out.println(-1); }
		}
	}

	static int nextBill(int[] a, int amt){
		int lo = 0, hi = a.length -1, mid;
		while (lo <= hi){
			mid = lo + (hi-lo)/2;
			if (a[mid] == amt){ return amt; }
			else if (a[mid] < amt){ lo = mid + 1; }
			else { hi = mid - 1; }
		}
		return a[Math.min(lo, hi)];
	}
}
