 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] arr = in.nextIntArray(1, n);
            int[] occ = new int[123456];
            TreeSet<Integer> memo = new TreeSet<>();
            boolean[] isRecord = new boolean[n + 1];
            int maxPrev = 0;
            for (int i = 1; i <= n; i++) {
                if (arr[i] > maxPrev) {
                    isRecord[i] = true;
                }
                maxPrev = Math.max(arr[i], maxPrev);
                Integer greater = memo.ceiling(arr[i]);
                if (greater != null && greater.equals(memo.last())) {
                    occ[greater]++;
                }
                memo.add(arr[i]);
                if (isRecord[i]) {
                    occ[arr[i]]--;
                }
            }
            int answer = 1;
            for (int i = 1; i <= n; i++) {
                if (occ[arr[i]] > occ[answer]) {
                    answer = arr[i];
                } else if (occ[arr[i]] == occ[answer]) {
                    answer = Math.min(arr[i], answer);
                }
            }
            out.println(answer);
        }

    }

    static class InputReader {
        private StringTokenizer tokenizer;
        private BufferedReader reader;

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        private void fillTokenizer() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
        }

        public String next() {
            fillTokenizer();
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int offset, int length) {
            int[] arr = new int[offset + length];
            for (int i = offset; i < offset + length; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

    }
