        long pre[]=new long[n/2+1];
        long min[]=new long[n/2+1];
        for(i=1;i<=n/2;i++){
            pre[i]=z-arr[i];
            pre[i]=pre[i-1]+pre[i];
        }
        min[0]=Long.MAX_VALUE;
        min[1]=pre[1];
        for(i=2;i<=n/2;i++)
            min[i]=Math.min(min[i-1],pre[i]);
        int f=0,ans=-1;
        for(i=0;i<=n/2;i++){
            if(sum>0 && sum+min[n/2-i]>0){
