    static int gcd(int a, int b) {
        if (a == 0)
            return b;
        if (b == 0)
            return a;
        if ((a == 1) || (b == 1))
            return 1;
        if (a == b)
            return a;
        if (a > b) {
            return gcd(a-b, b);
        } else return gcd(a,b-a);
