		return 0;
	}
	static int yV(char c)
	{
		if(c=='U')return 1;
		if(c=='D')return -1;
		return 0;
	}

	static boolean sim(int size)
	{
		int[] cur = new int[2];
		int i = 0 , j = 0;
		while(j<size)
		{
			cur[0] += xV(a[j]);
			cur[1] += yV(a[j++]);
		}
		--j;
		while(true)
		{
			if(valid(cur, size))
				return true;
			if(++j>=n)
				break;
			cur[0] -= xV(a[i]);
			cur[1] -= yV(a[i++]);
			cur[0] += xV(a[j]);
			cur[1] += yV(a[j]);
		}
		return false;
	}

	static boolean valid(int[] cur,int size)
	{
		int nx = vec[0]-cur[0] , ny = vec[1]-cur[1];
		nx = Math.abs(nx-x);
		ny = Math.abs(ny-y);
		if(nx+ny>size)return false;
		size-=nx;
		size-=ny;
//		if(nx+ny!=0)size%=nx+ny;
		return size%2==0;
	}

	static int solve()
	{
		int lo = 0 , hi = n , ans = -1;
		while(lo<=hi)
		{
			int mid = (lo+hi)>>1;
			if(sim(mid))
			{
				hi = mid-1;
				ans = mid;
			}
			else
				lo = mid+1;
		}
		return ans;
	}

