            int y = tot - a[1][0] - a[1][2];
            int z = tot - a[2][0] - a[2][1];

            if (x + y + z != tot ||
                    a[0][2] + y + a[2][0] != tot) {
                continue;
            }
            if (x + a[1][0] + a[2][0] != tot ||
                    y + a[0][1] + a[2][1] != tot ||
                    z + a[0][2] + a[1][2] != tot) {
                continue;
            }
            a[0][0] = x;
            a[1][1] = y;
            a[2][2] = z;
            break;
        }


        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                System.out.printf(Locale.ENGLISH, "%d ", a[i][j]);
            }
