		int a, b;

		public sort(int a, int b) {
			this.a = a;
			this.b = b;
		}

		public int compareTo(sort arg0) {
			if (this.a == arg0.a)
				return (this.b - arg0.b);
			return -(this.a - arg0.a);
		}
	}

