		pw.print(binsearch(2, Long.MAX_VALUE - 3));
		pw.close();
	}

	private static long binsearch(long l, long r) {
		long m = (l + r) / 2;
		if (ans(m) && !ans(m - 1)) {
			return m;
		}
		if (ans(m))
			return binsearch(l, m);
		else
			return binsearch(m + 1, r);
	}

	private static boolean ans(long m) {
		if (m < 0)
			return false;
		return (m - m / x >= cnt1 && m - m / y >= cnt2 && m - m / e >= cnt);
	}

	private static long gcd(long x, long y) {
		return y == 0 ? x : gcd(y, x % y);
