    public static int findOptimal(LinkedList<Integer> array){
        int optimalIndex = 0;
        int maxMinAdj = Integer.MIN_VALUE;

        for(int i=1; i<array.size()-1; i++){
            int minAdj = array.get(i-1)<array.get(i+1)? array.get(i-1):array.get(i+1);
            if(minAdj > maxMinAdj || (minAdj==maxMinAdj && array.get(i) < array.get(optimalIndex) )){
                optimalIndex =  i;
                maxMinAdj = minAdj;
            }
        }
        result += maxMinAdj;
        return optimalIndex;
    }
