    private int[] getDifficulty(int size, int[] positions) {
        int[] result = new int[size + 1];
        result[0] = 1;
        for (int i = 1; i < result.length; i++) {
            result[i] = getOneDifficulty(size, Arrays.copyOfRange(positions, 0, i)) + 1;
        }
        return result;
    }

    private int getOneDifficulty(int size, int[] positions) {
        Arrays.sort(positions);
        int l = 0;
        int r = positions.length - 1;
        if(positions[r] != size){
            return Arrays.copyOfRange(positions, l, positions.length).length;
        }
        while (l < r) {
            if (positions[r] - 1 == positions[r - 1]) {
                r--;
            }else {
                break;
            }
        }
        return Arrays.copyOfRange(positions, l, r).length;
    }

}
