    {
        in = new InputReader( System.in );
        out = new PrintWriter( System.out );
        solution();
        out.close();
    }

    /* Start the solution here */
    long n, x, y, c;

    long func(long t)
    {
        long left = Math.min( t, y - 1 );
        long right = Math.min( t, n - y );
        long up = Math.min( t, x - 1 );
        long down = Math.min( t, n - x );

        long ret = 1 + left + right + up + down;
        ret += square(t, left, up);
        ret += square(t, up, right);
        ret += square(t, right, down);
        ret += square(t, down, left);
        return ret;
    }

    long triangular(long n)
    {
        return n * (n+1) / 2;
    }

    private long square(long t, long A, long B)
    {
        if ( A > B )
        {
            long temp = A;
            A = B;
            B = temp;
        }
        if ( t >= A+B ) return A*B;
        if ( t < A ) return triangular( t-1 );
        else return A*B - triangular( (A+B)-t );
    }

    private void solution() throws IOException
    {
        n = in.nextLong();
        x = in.nextLong();
        y = in.nextLong();
        c = in.nextLong();

