class TaskB {
    char[][] grid;
    boolean[][] seen;
    int[] dx = {-1,1,0,0};
    int[] dy = {0,0,-1,1};
    void flood(int i, int j)
    {
        if ( i < 0 || j < 0 || i >= seen.length || j >= seen[0].length ) return;
        if ( grid[i][j] == 'W' ) return;
        if ( seen[i][j] ) return;
        seen[i][j] = true;
        for (int k=0; k<4; k++) flood( i + dx[k], j + dy[k] );
    }
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        grid = new char[ n+2 ][ m+2 ];
        Arrays.fill( grid[0], 'W' );
        for (int i = 1; i <= n; i++) grid[i] = ("W" + in.next() + "W").toCharArray();
        Arrays.fill( grid[n+1], 'W' );
        seen = new boolean[n+2][m+2];
        int cont = 0;
        for (int i=0; i < n+2; i++)
            for (int j = 0; j < m+2; j++)
                if ( !seen[i][j] && grid[i][j] == 'B' )
                {
                    cont++;
                    flood( i, j );
                }
        boolean ans = (cont == 1) ? true : false;
        for (int i = 1; i <= n; i++)
        {
            int cnt = 0;
            for (int j = 1; j < m+2; j++)
            {
                if ( grid[i][j] != grid[i][j-1] ) cnt++;
            }
            if ( cnt > 2 ) ans = false;
        }
        for (int j = 1; j <= m; j++)
        {
            int cnt = 0;
            for (int i = 1; i < n+2; i++)
            {
                if ( grid[i][j] != grid[i-1][j] ) cnt++;
            }
            if ( cnt > 2 ) ans = false;
        }
        if (ans) out.println( "YES" );
        else out.println( "NO" );
    }
}

