import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;
import java.util.Stack;

public class BmailComputerNetwork {
	public static void main(String args[]) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		ArrayList<ArrayList<Integer>> graph = new ArrayList<>();
		for(int i = 0; i<n; i++) {
			graph.add(new ArrayList<>());

		}

		for(int i = 0; i<n-1; i++) {
			int firstNode = i+1;
			int newNode = sc.nextInt() - 1;
			graph.get(firstNode).add(newNode);
			graph.get(newNode).add(firstNode);
		}

		//DFS
		boolean [] visited = new boolean[n];
		Stack<Integer> myStack = new Stack<>();

		myStack.push(0);
		while(!myStack.isEmpty()) {
			if(myStack.peek() == n-1){ 
				visited[n-1] = true;
				break;
			}
			if(visited[myStack.peek()]) { 
				myStack.pop();
				continue;
			}
			visited[myStack.peek()] = true;
			for(Integer child:graph.get(myStack.peek())) {
				if(!visited[child]) {
					myStack.push(child);
				}
			}
		}

		Stack<Integer> printStack = new Stack<>();
		while(!myStack.isEmpty()) {
			int p = myStack.pop();
			if(visited[p]) {
				printStack.push(p+1);
			}
		}
		while(!printStack.isEmpty()) {
			System.out.print(printStack.pop() + " ");
		}

	}
}
