        String[] routers = bi.readLine().split("\\s");
        for(int i=2;i<=n;i++){
            path[i] = Integer.parseInt(routers[i-2]);
        }
        list = new ArrayList<>();
        System.out.println(makePath(path, path[n], ""+n));
    }

    private static String makePath(int[] source, int nth, String path){
        if(source[nth]==1){
            return 1 + " " + nth + " "+ path;
        }else{
            boolean distinct = list.contains(nth);
            list.add(nth);
            return makePath(source, source[nth], distinct? path : nth+" "+path);
        }
    }
}
