    private final int n;
    private final long mod =998244353;

    public Main(int n, int[] numbers) {
        this.n = n;


        //we assume that the costs of all partitions are equal
        //Therefore, we only have to find the cost of one partition
        //and the number of possible partitions

        int[] part1 = new int[n];
        int[] part2 = new int[n];
        for (int i = 0; i < numbers.length/2; i++) {
            part1[i]=numbers[i];
            part2[i]=numbers[i+n];
        }

        Arrays.sort(part1);
        Arrays.sort(part2);


        long cost = 0;
        for (int i = 0; i < n; i++) {
            cost+=Math.abs(part2[n-1-i]-part1[i]);
        }
        cost%=mod;


        //Calculate the number of partitions
        //we choose n out of 2n for the first partition
        //2n!/n!/n!

