public class Reposts_522A {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());

        Map<String, List<String>> adj = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String[] l = br.readLine().split("\\s");
            if (adj.containsKey(l[2])) {
                adj.get(l[2].toLowerCase()).add(l[0].toLowerCase());
            } else {
                List<String> edges = new ArrayList<>();
                edges.add(l[0].toLowerCase());
                adj.put(l[2].toLowerCase(), edges);
            }
        }
        Map<String, Integer> max = new HashMap<>();
        System.out.println(bfs("polycarp", adj));
    }


    static int bfs(String start, Map<String, List<String>> adj) {

        int max = 1;
        Map<String, Boolean> visited = new HashMap<>();
        Queue<String> q = new LinkedList<>();
        visited.put(start, true);
        q.add(start);
        while (!q.isEmpty()) {
            String v = q.poll();
            List<String> edges = adj.get(v);
            if (edges == null) continue;
            for (String s : edges) {
                if (!visited.containsKey(s)) {
                    visited.put(s, true);
                    q.add(s);
                }
            }
            max++;
        }
        return max;
    }
}
