import java.util.*;
public class cutRibbon {
    static int n, a, b, c;
    static int[] nums;
        public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        a = sc.nextInt();
        b = sc.nextInt();
        c = sc.nextInt();
        nums = new int[n+1];
        Arrays.fill(nums, -2);
        int answer = solve(n);
        System.out.println(answer);
    }
    static int solve(int length){
        //called a "memoization check"
        if(nums[length] != -2) return nums[length];
        if(length==0) return nums[length] = 0;
        int ansA = -1;
        if(length-a>=0 && solve(length-a)!= -1) ansA = 1 + solve(length-a);
        int ansB = -1;
        if(length-b>=0 && solve(length-b)!= -1) ansB = 1 + solve(length-b);
        int ansC = -1;
        if(length-c>=0 && solve(length-c)!= -1) ansC = 1 + solve(length-c);
        int ret = Math.max(ansA, Math.max(ansB, ansC));
        return nums[length] = ret;
    }
}
