        int n = ni();
        int a[] = new int[n];
        for(int i = 0; i < n; i++)  a[i] = ni();
        HashMap <Integer, Integer> mp = new HashMap<>();
        int ans = 0;
        for(int i = 0; i < n; i++) {
            mp.put(a[i], mp.getOrDefault(a[i], 0) + 1);
            if(a[i] == 0)   ans++;
        }
        int undo[] = new int[n];
        int ind = 0;
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < n; j++) {
                if(i == j || (a[i] == 0 && a[j] == 0))   continue;
                ind = 0;
                int x = a[i], y = a[j];
                mp.put(x, mp.get(x) - 1);   undo[ind++] = x;
                mp.put(y, mp.get(y) - 1);   undo[ind++] = y;
                int sz = 2;
                while(true) {
                    int z = x + y;
                    if(mp.getOrDefault(z, 0) == 0) break;
                    mp.put(z, mp.get(z) - 1);   undo[ind++] = z;
                    x = y;  y = z;
                    sz++;
                }
                ans = Math.max(ans, sz);
                for(int k = 0; k < ind; k++)    mp.put(undo[k], mp.get(undo[k]) + 1);
            }
        }
        out.println(ans);
