class TaskA {

	public void solve(InputReader in,PrintWriter out) {
		int n=in.nextInt();
		int[] d=new int[n];
		for(int i=0;i<n;i++){
			d[i]=in.nextInt();
		}
		Arrays.sort(d);
		int u=d[0];
		while(true){
			boolean flag=false;
			for(int i=0;i<n;i++){
				if(d[i]%u==0)
					continue;
				else{
					flag=true;
					u=d[i]%u;
					break;
				}
			}
			if((!flag) || u==1)
				break;
		}
		int k=(d[n-1]-u)/u+1;
		k-=n;
		if(k%2==0){
			out.println("Bob");
		}
		else{
			out.println("Alice");
		}
	}
}

