			if (child == p)
				continue;
			dfs(child, v);
			subtree[v]+=subtree[child];
		}
		subtree[v]+=1;
	}
	public static long recur(int v, int p){
		long prod = subtree[v];
		long count = 1;
		for(int child : tree.get(v)){
			if (child == p)
				continue;
			prod*=count;
			prod%=num;
			count++;
			prod*=recur(child, v);
			prod%=num;
		}
		return prod;
	}

}


