		for (int l = 0, r = 1; l < 7; l++, r++) {
			int ai = Integer.valueOf(a.substring(l, r));
			int bi = Integer.valueOf(b.substring(l, r));
			int ci = ai + bi;
			c += ci;
		}

		return c;
	}

