		    count = 0;
			nxtStart=st.indexOf("AC",nxtStart)==-1 ? 0 : st.indexOf("AC",nxtStart); 
			nxtEnd=st.indexOf("CA",nxtStart);
			if (nxtEnd==-1) break;
