			l = nxtStart++; r = nxtEnd;
			while (nxtStart < nxtEnd) {
				if (st.charAt(nxtStart)=='C' && st.charAt(nxtEnd)=='C') count++;
				nxtStart++; nxtEnd--;
			}
			st.replace(l,r+2,"");
