			m = Math.max(m, s.charAt(i) - 'a');
		}
		int res = 0;
		int prev = -2;
		for (int i = m; i >= 0; --i) {
			StringBuilder sb = new StringBuilder();
			for (int j = 0; j < s.length(); ++j) {
				if (s.charAt(j) == 'a' + i) {
					if (prev >= 0 && prev == i - 1) {
						res++;
						continue;
					}
					if (j < s.length() - 1 && s.charAt(j + 1) == 'a' + i - 1) {
						res++;
						continue;
