	private static void calc(int []nums, char []op, boolean []flag, int step, long cur)
	{

		if (step == 0) 
		{

			for (int i=0;i < 4;++i)
				for (int j=i + 1;j < 4;++j)
				{
					flag[j] = flag[i] = true;
					calc(nums, op, flag, step + 1, op[step] == '+' ?nums[j] + nums[i]: nums[j] * nums[i]);
					flag[j] = flag[i] = false;
				}

		}
		else
		if (step <= 2)
		{
			int co = 0;
			int a,b;
			a = b = 0;

			for (int i=0;i < 4;++i)
			{
				if (!flag[i])
				{
					if (co == 0)
						a = nums[i];
					else
						b = nums[i];

					flag[i] = true;
					calc(nums, op, flag, step + 1, op[step] == '+' ?(cur + nums[i]): cur * nums[i]);
					flag[i] = false;
					++co;
				}
			}

			if (step == 1)
			{
				int temp = op[step] == '+' ?a + b: a * b;
				calc(nums, op, flag, step + 2, op[step + 1] == '+' ?cur + temp: cur * temp);

			}


		}
		else
			res = cur < res ?cur: res;


	}

}


