def chunks(iterable, n, fillvalue=None):
    """
    modified grouper function
    https://docs.python.org/3.5/library/itertools.html

    >>> list(chunks([1, 2, 3, 4, 5, 6, 7], 3))
    [(1, 2, 3), (4, 5, 6)]
    """
    args = [iter(iterable)] * n
    return zip(*args)


def solve(xss):
