		new B().run();
	}

	private void solve() throws Exception {
		int n = nextInt();
		String message;
		while(true) {
			message = nextLine();
			if(message.length() != 0) break;
		}
		int pieces[] = new int[1<<20], npieces = 0;
		int l = message.length(), now = 0;
		for(int i = 0; i < l; i++) {
			char c = message.charAt(i);
			if(c == '.' || c == '?' || c == '!') {
				pieces[npieces++] = now + 1;
				//out.printf("%d\n", now);
				now = -1;
			}
			else {
				now++;
			}
		}
		int f[] = new int[1<<20];

		for(int i = 0; i < npieces; i++) {
			f[i+1] = 1 << 29;
			if(pieces[i] <= n) {
				f[i+1] = 1 + f[i];
			}
			int sump = pieces[i], j = i-1;
			while(j >= 0) {
				sump += 1 + pieces[j];
				if(sump > n) break;
				f[i+1] = min(f[i+1], f[j] + 1);
				j--;
			}
		}

		if(f[npieces] >= (1 << 29)) out.printf("Impossible\n");
		else out.printf("%d\n", f[npieces]);
	}

	private BufferedReader in;
	private PrintWriter out;
	private StringTokenizer tokenizer;

	public void run() {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			tokenizer = null;
			out = new PrintWriter(System.out);
			solve();
			in.close();
			out.close();
		} catch (Exception e) {
			e.printStackTrace();
			System.exit(1);
		}
	}

	private int nextInt() throws IOException {
		return Integer.parseInt(nextToken());
	}

	private long nextLong() throws IOException {
		return Long.parseLong(nextToken());
	}

	private double nextDouble() throws IOException {
		return Double.parseDouble(nextToken());
	}

	private String nextLine() throws IOException {
		return new String(in.readLine());
	}

	private String nextToken() throws IOException {
		while (tokenizer == null || !tokenizer.hasMoreTokens()) {
			tokenizer = new StringTokenizer(in.readLine());
		}
		return tokenizer.nextToken();
	}
