	static int left(int i) {
		for (int j = 0; j < m; j++)
			if (aa[i][j] == 'B')
				return j;
		return m;
	}
	static int right(int i) {
		for (int j = m - 1; j >= 0; j--)
			if (aa[i][j] == 'B')
				return j;
		return -1;
	}
	static boolean row(int i, int l, int r) {
		if (l > r) {
			int tmp = l;
			l = r;
			r = tmp;
		}
		for (int j = l; j <= r; j++)
			if (aa[i][j] != 'B')
				return false;
		return true;
	}
	static boolean col(int j, int u, int d) {
		if (u > d) {
			int tmp = u;
			u = d;
			d = tmp;
		}
		for (int i = u; i <= d; i++)
			if (aa[i][j] != 'B')
				return false;
		return true;
	}
	static boolean check(int i1, int j1, int i2, int j2) {
		return row(i1, j1, j2) && col(j2, i1, i2) || row(i2, j1, j2) && col(j1, i1, i2);
	}
