	static long smallestPrimeFactor(long n) {

	    if( (n&1) == 0) return 2;
	    long limit = (long)Math.sqrt(n);

	    long f=3;
	    while(f<=limit) {
	        if(n%f==0 && isPrime(f)) 
	            return f;
	        f += 2;
	    }

	    return n;
	}

	static boolean isPrime(long n) {
	    if(n==2) return true;
	    if(n%2==0 || n==1) return false;
	    long limit = (long)Math.sqrt(n);
	    for(long i=3;i<=limit;i+=2)
	        if(n%i==0) return false;
	    return true;
	}

	static final long P = (long)1e9 + 7;

	static long power(long x, long y) 
	{ 
			long res = 1;      
			x = x % P;  
			while (y > 0) 
			{ 
					if((y & 1)==1) 
							res = (res * x) % P; 
					y = y >> 1;  
					x = (x * x) % P;  
			} 
			return res; 
	} 

	static long modProduct(long... a) {
		long sum = 1;
		for(long x : a) 
			sum = ( (sum%P) * (x%P) )%P;

		return sum;
	}


	static long modAdd(long... a) {
		long sum = 0;
		for(long x : a) {
			sum = ( (sum%P) + (x%P) )%P;
		}

		return sum;
	}

