class TaskC {
	public void solve(int testNumber, Scanner in, PrintWriter out) {
        int n = in.nextInt();
        long memory = in.nextLong();
        long a = in.nextLong(), b = in.nextLong();
        Client[] c = new Client[n];
        for (int i=0; i<n; i++) {
            long x = in.nextLong(), y = in.nextLong();
            c[i] = new Client(i+1, x*a+y*b);
        }
        Arrays.sort(c);
        long total = 0;
        int i = 0;
        int no = 0;
        while (true) {
            if (total + c[i].size > memory) break;
            total += c[i++].size;
            no++;
            if (i >= c.length) break;
        }
        out.println(no);
        String clients = new String("");
        for (i=0; i<no; i++) out.print(clients + c[i].number + " ");
        out.println(clients.trim());
	}
}

class Client implements Comparable<Client> {
    long size = 0; int number = 0;
    Client(int n, long s) { number = n; size = s; }

    public int compareTo(Client b) {
        if (size < b.size) return -1;
        if (size > b.size) return 1;
        return number-b.number;
    }
}
