		int n = in.nextInt();
		int vb = in.nextInt();
		int vs = in.nextInt();
		ArrayList<Integer> stops = new ArrayList<>();

		for (int i = 0; i < n; i++)
			stops.add(in.nextInt());

		int xu = in.nextInt();
		int yu = in.nextInt();

		int firstStop = stops.get(0);
		int secondStop = stops.get(1);

		if ((xu >= firstStop && xu <= secondStop) || xu < 0)
			System.out.println(2);
		else {
			double min = Integer.MAX_VALUE;
			int minIndex = -1;
			for (int i = 1; i < n; i++) {
				int x = stops.get(i);
				double t = getTime(x, xu, yu, vs, vb);

				if (t < min) {
					min = t;
					minIndex = i;
				} else if (t == min) {
					int x1 = stops.get(minIndex);
					int y1 = 0;
					int x2 = stops.get(i);
					int y2 = 0;

					double dist1 = getDistance(x1, y1, xu, yu);
					double dist2 = getDistance(x2, y2, xu, yu);
					if (dist1 > dist2) {
						minIndex = i;
					}

				}
			}
			System.out.println(minIndex + 1);
		}

	}

	private static double getTime(int x, int xu, int yu, int vs, int vb) {
		double t1 = x / (vb * 1.0);
		double dist = getDistance(x, 0, xu, yu);
		double t2 = dist / vs;

		return t1 + t2;
	}

	private static double getDistance(double x1, double y1, double x2, double y2) {
		double d1 = Math.pow(x1 - x2, 2);
		double d2 = Math.pow(y1 - y2, 2);
		return Math.sqrt(d1 + d2);
	}

}
