		s = r.readLine();
		String[] sp = s.split(" ");
		int[] arr = new int[sp.length];
		for (int i = 0; i < arr.length; i++) {
			arr[i] = new Integer(sp[i]);
		}
		double low = 10;
		double high = 1e7;
		int itr =200;
		while (itr-- > 0) {
			double mid = (low + high) / 2;
			if (can(mid, arr)) {
				high = mid;
			} else {
				low = mid;
			}
		}
		high -= 1e-9;
		int interval = arr[0];
		int index = 0;
		for (int i = 1; i < arr.length; i++) {
			if (arr[i] != arr[i - 1] + interval) {
				index = i+1;
				break;
			}
		}
		double temp = 10.0 / index;
		if(index==0)temp=0;
		double high2 = interval * 10 + temp;
		high=high2+0.1;
		int n1 = get(high, arr);
		int n2 = get(high2, arr);
//		System.out.println(n1+" "+n2+" "+high+" "+high2);
		if (n1 == n2 && temp!=0) {
			System.out.println("unique");
			System.out.println(n2);
		} else
			System.out.println("not unique");

	}

	private static boolean can(double mid, int[] arr) {
		double curr = mid;
		int next = (int) (curr / 10);

		for (int i = 0; i < arr.length; i++) {

			if (next < arr[i]) {
				return false;
			} else if (next > arr[i]) {
				return true;
			} else {
				double rem = curr % 10;
				rem += mid;

				next = next + (int) (rem / 10);

			}
		}
		return true;
	}

	private static int get(double mid, int[] arr) {
		double curr = mid;
		curr -= arr[0] * 10;
		curr += mid;
		for (int i = 1; i < arr.length; i++) {
			curr -= (arr[i] - arr[i - 1]) * 10;
			curr += mid;
		}
		int last=arr[arr.length-1];
//		curr+=1e-8;
//	System.out.println(curr);
		last+=(curr/10);
		return last;
	}
}
