            s.solve(i, in, out);
        }
        out.close();
    }
}
class Solver {
    HashSet<Integer>[] v;
    boolean[] visited;
    int[] color;
    void solve(int test_number, InputReader in, PrintWriter out) throws IOException {
        int n = in.nextInt();
        v = new HashSet[n];
        visited = new boolean[n];
        color = new int[n];
        for (int i = 0; i < n; i++) {
            v[i] = new HashSet<>();
        }
        for (int i = 0; i < n - 1; i++) {
            int x = in.nextInt() - 1;
            int y = in.nextInt() - 1;
            v[x].add(y);
            v[y].add(x);
        }
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                color[i] = 0;
                bi(i);
            }
        }
        ArrayList<Integer> zero = new ArrayList<>(), one = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (color[i] == 1) one.add(i);
            else zero.add(i);
        }
        long ans = 0;
        for (Integer x : zero) {
            ans += one.size() - v[x].size();
        }
        out.println(ans);
    }

    private boolean bi(int s) {
        visited[s] = true;
        for (Integer x : v[s]) {
            if (!visited[x]) {
                color[x] = 1 - color[s];
                bi(x);
            }
            else if (color[x] == color[s]) return false;
        }
        return true;
    }
}


