    static final boolean stdin = true;
    static final String filename = "";
    static FastScanner br;
    static PrintWriter pw;

    public static void main(String[] args) throws IOException {

        if (stdin) {
            br = new FastScanner();
            pw = new PrintWriter(new OutputStreamWriter(System.out));
        } else {
            br = new FastScanner(filename + ".in");
            pw = new PrintWriter(new FileWriter(filename + ".out"));
        }

        Solver solver = new Solver();
        solver.solve(br, pw);
    }

    static class Solver {
        public void solve(FastScanner br, PrintWriter pw) throws IOException {
        	int n = br.nextInt(), m = br.nextInt(), min = Integer.MAX_VALUE;
        	int[] out = new int[n];
        	for(int i = 0; i < m; i++){
        		int running = 0;
        		int a = br.nextInt()-1;
        		int b = br.nextInt();
        		boolean overflow = false;
        		for(int j = a; j < b; j++){
        			if(running>1000000000){
        				overflow = true;
        				running = 0;
        			}
        			out[j] = Math.min(out[j],running);
        			running++;
        		}
        		if(overflow)min = Math.min(min, 1000000000);
        		else min = Math.min(min, running);
        	}
        	pw.println(min);
        	for(int i = 0; i < n-1; i++){
        		pw.print(out[i] + " ");
        	}
        	pw.print(out[n-1]);
            pw.close();
        }

    }

