public class Repaints {
	int n;
	int m;	

	int oldNum, newNum;

	public Repaints(int n, int m) {
		this.n = n;
		this.m = m;
	}

	public int solve(int x) {
		int solution = 0;
		for (int i = 0; i < x; i++) {
			solution = 0;

			if (n > 0 && m > 0)
				return 0;

			oldNum = (m * n + 1) / 2;

			m -= 2;
			n -= 2;

			if (n > 0 && m > 0)
				newNum = (m * n + 1) / 2;		
			else newNum = 0;

			solution = oldNum - newNum;			

		}

		return solution;
	}

