    public void solve() {
        int[][] a = new int[3][3];
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++)
                a[i][j] = in.nextInt();
        int n = in.nextInt();
        long[][][] dp = new long[3][3][n + 1];
        for (int i = 1; i <= n; i++) {
            for (int from = 0; from < 3; from++) {
                for (int to = 0; to < 3; to++) {
