    static long dfs(ArrayList<Integer>[] adj, int u, int p){
        long ret = 1;
        int idx = 2;
        if(p == -1){
            idx--; ret = sz[u];
        }
        for(int i = 0; i<adj[u].size(); i++){
            if(adj[u].get(i) == p) continue;
            ret *= (idx*(dfs(adj, adj[u].get(i), u)))%mod;
            idx++;
            ret %= mod;
        }
        return ret;
    }
    static void sz(ArrayList<Integer>[] adj, int u, int p){
        sz[u] = 1;
        for(int n : adj[u]){
            if(n == p) continue;
            sz(adj, n, u);
            sz[u] += sz[n];
        }
    }
}
