			topDownSums[j][0] = grid[0][j] == '*' ? 1 : 0;
			for (int i = 1; i < n; i++) {
				topDownSums[j][i] = grid[i][j] == '*' ? 1 : 0;
				topDownSums[j][i] += topDownSums[j][i - 1];
			}

			bottomUpSums[j][n - 1] = grid[n - 1][j] == '*' ? 1 : 0;
			for (int i = n - 2; i >= 0; i--) {
