	}

	static boolean isHostName (String s) {
		boolean ok = isCorrectLength(s, 32);
		if (!ok) return ok;
		for (char ch : s.toCharArray()) {
			if (ch!='_' && ch!='.' && !Character.isLetterOrDigit(ch)) {
				ok=false; break;
			}
		}
		return ok;
	}

	static boolean isCorrectLength (String s, int len) {
		return (s.length()<=len && s.length()>0);
	}

	static void solve() {
		Scanner sc = new Scanner(System.in);
		String o = sc.next();
		String[] tok = o.split("@");
		boolean ok = (tok.length==2 && o.indexOf("@")==o.lastIndexOf("@"));
		if (ok) {
			ok&=(isUserNameOrResource(tok[0]));
			if (tok[1].indexOf("/")==-1) ok&=isHostName(tok[1]);
			else ok&=!(tok[1].endsWith("/"));
			if (tok[1].indexOf(".")!=-1) {
