import java.util.*;

public class Remove {
	public static int numRecord(int[] p) {
		if (p.length == 0) return 0;
		int max = p[0], ans = 0;
		for (int i = 1; i < p.length; i++) if (p[i] > max) {
			ans++;
			max = p[i];
		}
		return ans;
	}
	public static void main(String[] args) {
		Scanner f = new Scanner(System.in);
		int n = f.nextInt(), max = 0;
		int[] values = new int[n];
		boolean[] record = new boolean[n];
		for (int i = 0; i < n; i++) {
			values[i] = f.nextInt();
			if (values[i] > max) {
				record[i] = true;
				max = values[i];
			}
		}
		//We have an O(N) solution: for each record, we consider the array between that number and the next record, w/ the starting number being the previous record, and count.
		int ans = -1, benefit = -1, prev = 0, i = 0;
		while (i < record.length) {
			int start = i;
			//Get to the next instance
			i++;
			while (i < record.length && !record[i]) i++;
			if (start == 0) {
				int[] good = Arrays.copyOfRange(values, start + 1, i);
				ans = start;
				benefit = numRecord(good);
			}
			else {
				int[] good = Arrays.copyOfRange(values, start, i);
				good[0] = values[prev];
				int b = numRecord(good) - 1;
				if (b > benefit || (b == benefit && values[start] < values[ans])) {
					ans = start;
					benefit = b;
				}
			}
			prev = start;
		}
		if (benefit == 0) {		//We compare our answer to non-peaks and find the smallest.
			for (i = 0; i < n; i++) if (!record[i] && values[i] < values[ans]) ans = i;
		}
		System.out.println(values[ans]);
	}
}
