			main.m = scanner.nextInt();
			main.a = new int[main.n];
			long sum = 0;
			long maxIndex = 0;
			for (int i = 0; i < main.n; ++i) {
				main.a[i] = scanner.nextInt();
				sum += main.a[i];
				if (main.a[i] != 0) {
					maxIndex = i + 1;
				}
			}
			long maxTime = sum + maxIndex;
			long minTime = maxIndex;
			long mid = 0;
			while (minTime < maxTime) {
				mid = minTime + (maxTime - minTime) / 2;
				if (main.judge(mid)) {
					maxTime = mid;
				} else {
					minTime = mid + 1;
				}
			}
			System.out.println(maxTime);
		}

	}

	public boolean judge(long time) {

		int curIndex = 0;
		int curLeft = a[0];
		for (int i = 0; i < m; ++i) {
			int lastIndex = -1;
			long curTime = time;
			for (; curIndex < n;) {
				if (curLeft > 0) {
					curTime -= (curIndex - lastIndex);
					if (curTime >= curLeft) {
						curTime -= curLeft;
						lastIndex = curIndex;
						++curIndex;
						if (curIndex < n) {
							curLeft = a[curIndex];
						}
						continue;
					} else {
						if (curTime > 0) {
							curLeft -= curTime;
						}
						break;
					}
				} else {
					++curIndex;
					if (curIndex < n) {
						curLeft = a[curIndex];
					}
				}
			}
			if (curIndex >= n) {
				return true;
			}
		}
		return false;
	}

