public class Abood2D {

	static final int MOD = (int) 1e9 + 7;
	static int fac[];
	static int modInv[];
	static int pow(int x, int p) {
		if(p == 0)
			return 1;

		int ans = 1;
		if(p % 2 == 1)
			ans *= x;

		int c = pow(x, p / 2);

		ans = (int) ((1l * ((1l * ans * c) % MOD) * c) % MOD);

		return ans;
	}

	static int nCk(int N, int K) {
		return (int) ((((1l * fac[N] * modInv[K]) % MOD) * modInv[N - K]) % MOD);
	}


	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		int t = sc.nextInt();

		fac = new int[100001];
		modInv = new int[100001];


		fac[0] = 1;
		for (int j = 1; j < fac.length; j++) {
			fac[j] = (int) ((1l * fac[j - 1] * j) % MOD);
			modInv[j] = pow(j, MOD - 2);
		}

		for (int i = 0; i < t; i++) {
			String S = sc.next();
			int n = S.length();
			int total = 0;
			for (int j = 0; j < S.length(); j++)
				total += S.charAt(j) - 'a';



			long ans = nCk(total + n - 1, n - 1);


			for (int j = 1; ; j++) {
				if(total / (j * 26) == 0)
					break;

				if(j % 2 == 1)
					ans = ((1l * ans - 1l * nCk(total - j * 26 + n - 1, n - 1) * nCk(n, j)) % MOD + MOD) % MOD;
				else
					ans = ((1l * ans + 1l * nCk(total - j * 26 + n - 1, n - 1) * nCk(n, j)) % MOD + MOD) % MOD;
			}

			out.println((ans - 1 + MOD) % MOD);


		}



		out.flush();

	}



