import java.util.*;

public class D {
	static final int MOD = 1000000007;

	static long rec(int [] assignment, int cur){
		if (cur == assignment.length){
			final int [] visited = new int[assignment.length];
			for (int i = 1; i < assignment.length; ++i){
				if (visited[i] == 0){
					int t = i;
					do{
						visited[t] = i;
						t = assignment[t];
					}while (visited[t] == 0);
					if (i == 1){
						int l = t;
						boolean ok = false;
						do{
							if (l == 0){
								ok = true;
								break;
							}
							l = assignment[l];
						}while (l != t);
						if (!ok){
							return 0;
						}
					}else if (visited[t] == i){
						return 0;
					}
				}
			}
			return 1;
		}
		long res = 0;
		for (int i = 0; i < assignment.length; ++i){
			assignment[cur] = i;
			res += rec(assignment, cur + 1);
			res %= MOD;
		}
		return res;
	}

	public static void main(String [] args){
		Scanner s = new Scanner(System.in);
		final int n = s.nextInt();
		final int k = s.nextInt();
		long res = 1;
		for (int i = 0; i < n - k; ++i){
			res *= (n - k);
			res %= MOD;
		}
		res *= rec(new int[k], 0);
		res %= MOD;
		System.out.println(res);
		s.close();
	}
}
