    private static void sport(int[] a) {
        int n = a.length;
        int[] l = new int[n];
        int[] r = new int[n];
        l[0] = 1;
        for (int i = 1; i < n; i++) {
            if (a[i] > a[i - 1]) {
                l[i] = l[i - 1] + 1;
            } else {
                l[i] = 1;
            }
