        int ans = Math.max(l[n - 1], r[0]);
        for (int i = 1; i < n - 1; i++) {
            if (a[i - 1] + 1 < a[i + 1]) {
                ans = Math.max(ans, l[i - 1] + r[i + 1] + 1);
            }
        }
        System.out.println(ans);
