		sc.close();
	}

	static int solve(int[] a) {
		return Arrays.stream(a).filter(x -> !isPerfectSquare(x)).max().getAsInt();
	}

	static boolean isPerfectSquare(int x) {
		if (x < 0) {
			return false;
		}

		int root = (int) Math.round(Math.sqrt(x));
		return root * root == x;
	}
}
