            C[n] = input.nextInt();
        }
        int limit = 1 << N;
        int answer = 0;
        for (int mask=1; mask<limit; mask++) {
            if (Integer.bitCount(mask) == 1) continue;
            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            int sum = 0;
            for (int bit=0; bit<N; bit++) {
                if ((mask&(1<<bit)) != 0) {
                    min = Math.min(min, C[bit]);
                    max = Math.max(max, C[bit]);
                    sum += C[bit];
                }
            }
            if (L <= sum && sum <= R && max-min >= X) {
                answer++;
            }
        }
