        int n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();

        long ans = 0;
        int[] b = new int[n];
        int m = 0;
        for (int i = 0; i < n; i++) {
            while (m > 1 && b[m - 1] <= Math.min(b[m - 2], a[i])) {
                ans += Math.min(b[m - 2], a[i]);
                m--;
