public class ChainReaction {

	public static void main(String[] args) {
		int dpConstant = (int) (Math.pow(10, 6) + 1);
		int[] dp = new int[dpConstant];
		int[] beaconArray = new int[dpConstant];
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		for (int i = 0; i < n; i ++) {
			int index = scan.nextInt();
			beaconArray[index] = scan.nextInt();
		}

		int result = 0;
		dp[0] = beaconArray[0] == 0 ? 0 : 1;
		for (int i = 1; i < dpConstant; i ++) {
			if (beaconArray[i] == 0) dp[i] = dp[i - 1];
			else {
				if (beaconArray[i] >= i) dp[i] = 1;
				else dp[i] = dp[i - beaconArray[i] - 1] + 1;
			}

			result = Math.max(result, dp[i]);
		}

		System.out.println(n - result);
	}

}
