public class d {
    final int N = 1_000_000;

    class pair {
        long x, y;
        pair(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    long sumOfSquares(long n) {
        return n * (n + 1) * (2 * n + 1) / 6;
    }

    long sum(long n) {
        return n * (n + 1) / 2;
    }

    long count(long n, long m) {
        long x = Math.min(n, m) - 1, y = sum(Math.min(n, m) - 1);
        return (n * n * m) - (y * m) - (y * n) + sumOfSquares(x);
    }

    private void solve() throws IOException {
        long x = nextLong();
        List<pair> p = new ArrayList<>();
        for (long n = 1l; n <= N; ++n) {
            long y = x + n * (n + 1) * (n - 1) / 6;
            long m = n * (n + 1) / 2;

            if (y > 0 && y % m == 0) {
                m = y / m;
                if (n <= m) {
                    p.add(new pair(n, m));
                    if (n != m) {
                        p.add(new pair(m, n));
                    }
                }
            }
        }

        Collections.sort(p, (a, b) -> Long.compare(a.x, b.x));

