import java.io.*;
import java.util.StringTokenizer;
import java.util.TreeMap;

public class Main {

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));

		StringTokenizer st = new StringTokenizer(br.readLine());

		int w = Integer.parseInt(st.nextToken());
		int h = Integer.parseInt(st.nextToken());
		int n = Integer.parseInt(st.nextToken());

		TreeMap<Integer, Integer> idxHs = new TreeMap<>();
		TreeMap<Integer, Integer> idxWs = new TreeMap<>();

		TreeMap<Integer, Integer> Hs = new TreeMap<>();
		TreeMap<Integer, Integer> Ws = new TreeMap<>();

		idxHs.put(0, h);
		idxWs.put(0, w);
		Hs.put(h, 1);
		Ws.put(w, 1);

		for (int i = 0; i < n; i++) {

			st = new StringTokenizer(br.readLine());

			String dir = st.nextToken();
			int cut = Integer.parseInt(st.nextToken());

			if (dir.equals("H")) {

				int idx = idxHs.floorKey(cut);
				int last = idxHs.get(idx);

				idxHs.put(idx, cut - idx);
				idxHs.put(cut, last - cut + idx);

				if (Hs.get(last) == 1) {
					Hs.remove(last);
				} else {
					Hs.put(last, Hs.get(last) - 1);
				}

				if (Hs.containsKey(cut - idx)) {
					Hs.put(cut - idx, Hs.get(cut - idx) + 1);
				} else {
					Hs.put(cut - idx, 1);
				}

				if (Hs.containsKey(last - cut + idx)) {
					Hs.put(last - cut + idx, Hs.get(last - cut + idx) + 1);
				} else {
					Hs.put(last - cut + idx, 1);
				}

			} else {

				int idx = idxWs.floorKey(cut);
				int last = idxWs.get(idx);

				idxWs.put(idx, cut - idx);
				idxWs.put(cut, last - cut + idx);

				if (Ws.get(last) == 1) {
					Ws.remove(last);
				} else {
					Ws.put(last, Ws.get(last) - 1);
				}

				if (Ws.containsKey(cut - idx)) {
					Ws.put(cut - idx, Ws.get(cut - idx) + 1);
				} else {
					Ws.put(cut - idx, 1);
				}

				if (Ws.containsKey(last - cut + idx)) {
					Ws.put(last - cut + idx, Ws.get(last - cut + idx) + 1);
				} else {
					Ws.put(last - cut + idx, 1);
				}

			}

			long ans = Ws.lastKey();

			ans *= Hs.lastKey();

			bw.write(ans + "\n");

		}

		bw.close();
	}

}
