import java.util.Scanner;
import java.math.*; 

public class Main
{
    static int n, l, r, q_l, q_r;
    static int w[];
    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        l = sc.nextInt();
        r = sc.nextInt();
        q_l = sc.nextInt();
        q_r = sc.nextInt();

        w = new int[n];
        for(int i = 0; i < n; i++) w[i] = sc.nextInt();

        int ans = solve();
        System.out.println(ans);
    }

    public static int solve() {
        int ret = java.lang.Integer.MAX_VALUE;
        int L = 0, R = n-1;
        while(L <= R) {
            //System.out.println("here");
            int M_L = (L*2+R)/3;
            int M_R = (L+R*2)/3;

            int ans_1 = calc(M_L);
            int ans_2 = calc(M_R);

            ret = Math.min(ret, Math.min(ans_1, ans_2));

            if(ans_1 < ans_2) {
                R = M_R - 1;
            }
            else {
                L = M_L + 1;
            }
        }
        return ret;
    }

    public static int calc(int x) {
        int ret = 0;

        for(int i = 0; i < n; i++) {
            if(i <= x) ret += w[i]*l;
            else ret += w[i]*r;
        }

        int sum_l = x + 1;
        int sum_r = n - sum_l;

        int sum = Math.max(Math.abs(sum_l - sum_r) - 1, 0);
        if(sum_l > sum_r) ret += sum*q_l;
        else ret += sum*q_r;
        return ret;
    }
}
