    static class TaskA {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            TreeSet<Tree> neg = new TreeSet<>();
            TreeSet<Tree> pos = new TreeSet<>();
            for (int i = 0; i < n; i++) {
                int x = in.nextInt();
                int a = in.nextInt();
                if (x < 0) neg.add(new Tree(-x, a));
                if (x > 0) pos.add(new Tree(x, a));
            }
            int ans = 0;
            int m = Math.min(neg.size(), pos.size());
            if (neg.size() == pos.size()) {
                ans = sum(neg, m) + sum(pos, m);
            } else if (neg.size() > pos.size()) {
                ans = sum(neg, m + 1) + sum(pos, m);
            } else {
                ans = sum(neg, m) + sum(pos, m + 1);
            }
            out.println(ans);
        }

        private int sum(TreeSet<Tree> set, int size) {
            int ans = 0;
            while (size > 0) {
                ans += set.pollFirst().a;
                size--;
            }
            return ans;
        }

        private static class Tree implements Comparable<Tree> {
            private int x;
            private int a;

            public Tree(int x, int a) {

                this.x = x;
                this.a = a;
            }


            public int compareTo(Tree o) {
                return this.x - o.x;
            }

        }

    }

