    private PrintWriter out;

    private void solve() {
        int n = in.nextInt();
        int[] a = new int[n];
        int sum = 0;
        for (int i = 0; i < n; ++i) {
            a[i] = in.nextInt();
            sum += a[i];
        }
        if (sum % 3 != 0) {
            out.println(0);
            return;
        }
        sum /= 3;
        int p2 = 0;
        int balance = 0;
        for (int i = 0; i < n - 1; ++i) {
            balance += a[i];
            if (balance == sum * 2) {
                ++p2;
            }
        }
        long ans = 0;
        balance = 0;
        for (int i = 0; i < n - 1; ++i) {
            balance += a[i];
            if (balance == sum * 2) {
                --p2;
            }
            if (balance == sum) {
                ans += p2;
            }
        }
        out.println(ans);
    }

