    public static void runBFS(boolean[][] mat, int i, int j, int H, int W){
        Queue<Par> q = new LinkedList<>();
        q.add(new Par(i, j));
        mat[i][j] = false;
        while(!q.isEmpty()){
            Par cur = q.remove();
            int ci = cur.i;
            int cj = cur.j;

            //gore
            if(ci > 0 && mat[ci-1][cj]){
                mat[ci-1][cj] = false;
                q.add(new Par(ci-1, cj));
            }

            //dole
            if(ci < (H-1) && mat[ci+1][cj]){
                mat[ci+1][cj] = false;
                q.add(new Par(ci+1, cj));
            }

            //levo
            if(cj > 0 && mat[ci][cj-1]){
                mat[ci][cj-1] = false;
                q.add(new Par(ci, cj-1));
            }

            //desno
            if(cj < (W-1) && mat[ci][cj+1]){
                mat[ci][cj+1] = false;
                q.add(new Par(ci, cj+1));
            }
        }
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int H = sc.nextInt();
        int W = sc.nextInt();

        boolean[][] mat = new boolean[H][W]; //false by default

        for(int i = 0; i<H; i++){
            String line = sc.next();
            for(int j = 0; j<W; j++){
                if(line.charAt(j) == 'B'){
                    mat[i][j] = true;
                }
            }
        }

        int counter = 0;
        for(int i = 0; i<H; i++){
            for(int j = 0; j<W; j++){
                if(mat[i][j]){
                    counter++;
                    runBFS(mat, i, j, H, W);
                }
            }
        }
        System.out.println(counter);
    }
}

