        OutputStream os;
        try {
            is = new FileInputStream("input.txt");
            os = new FileOutputStream("output.txt");
        } catch (FileNotFoundException e) {
            is = System.in;
            os = System.out;
        }
        InputReader in = new InputReader(is);
        PrintWriter out = new PrintWriter(os);
        Contest contest = new Contest(in, out);
        contest.solve();
        out.close();
    }

    static class Contest {
        InputReader in;
        PrintWriter out;
        public Contest(InputReader in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }


        public void solve() {
            int l = 0, r = 0, u = 0, d = 0;
            String s = in.next();
            int n = s.length();
            for(int i = 0; i < n; i++)
            {
                if(s.charAt(i) == 'L')
                    l++;
                else if(s.charAt(i) == 'R')
                    r++;
                else if(s.charAt(i) == 'U')
                    u++;
                else
                    d++;
            }
            int dx = Math.abs(l - r);
            int dy = Math.abs(u - d);
            if(dx % 2 == dy % 2)
            {
                out.print(dx / 2 + dy / 2 + (dx % 2));
            }
            else
                out.print(-1);
        }
    }

