public class c {
    final int N = 18;

    <T> void add(Map<T, Integer> map, String op, T val, int inc) {
        if (!map.containsKey(val) && "+".equals(op)) {
            map.put(val, 0);
        }
        map.put(val, map.get(val) + inc);
    }

    String prepend(String pattern) {
        while (pattern.length() < N) {
            pattern = "0" + pattern;
        }

        return pattern;
    }

    String makePattern(long val) {
        String pattern = "";

        while (val > 0) {
            pattern =  (val % 2) + pattern;
            val /= 10;
        }

        return prepend(pattern);
    }

    private void solve() throws IOException {
        Map<String, Integer> pattern = new HashMap<>();
        Map<Long, Integer> count = new HashMap<>();
        int t = nextInt();

        for (int i = 0; i < t; ++i) {
            String op = next();
            long val = nextLong();
            String valPattern = makePattern(val);

            if ("+".equals(op)) {
                add(count, op, val, 1);
                add(pattern, op, valPattern, 1);
            } else if ("-".equals(op)) {
                add(count, op, val, -1);
                add(pattern, op, valPattern, -1);
            } else {
                String pat = prepend(val + "");
                int cnt = 0;

                if (pattern.containsKey(pat)) {
                    cnt = pattern.get(pat);
                }

                System.out.println(cnt);
            }
