        @Override
        public int compare(List<Integer> l1, List<Integer> l2) {
            for (int i = 0; i < l1.size(); ++i) {
                if (l1.get(i).compareTo(l2.get(i)) != 0) {
                    return l1.get(i).compareTo(l2.get(i));
                }
            }
            return 0;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(f.readLine());
        int N = Integer.parseInt(st.nextToken());
        int a = Integer.parseInt(st.nextToken());
        int b = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        List<Integer> list = new ArrayList<>(N);
        StringTokenizer ab = new StringTokenizer(f.readLine());
        for (int i = 0; i < N; i++) {
            int c = Integer.parseInt(ab.nextToken());
            list.add(c);
        }
        List<Integer> skips = new ArrayList<>(N);
        for (int i = 0; i < list.size(); i++) {
            int left = list.get(i) % (a + b);
            if ((a + b) >= list.get(i)) {
                if (list.get(i) <= a) {
                    skips.add(0);
                } else {
                    double temp = list.get(i) - a;
                    int add = (int) Math.ceil(temp / a);
                    skips.add(add);
                }
            } else if (left == 0) {
                double temp = b;
                int add = (int) Math.ceil(temp / a);
                skips.add(add);
            } else if (left <= a) {
                skips.add(0);
            } else {
                double temp = (left - a);
                int add = (int) Math.ceil(temp / a);
                skips.add(add);
            }
        }
        // System.out.println(skips);
        Collections.sort(skips);
        int max = 0;
        for (int i = 0; i < skips.size(); i++) {
            if (k >= skips.get(i)) {
                k -= skips.get(i);
            } else {
                break;
            }
            max++;
        }
        out.println(max);
        out.close();

    }

}
