import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;

public class Safe {

    static int n, m;
    static long[] tries;
    static int[] numRights;

    static boolean violates(long code, int len) {
        for (int i = 0; i < tries.length; ++i) {
            if(len == n && tries[i] == code) return true;
            long diff = tries[i]^code;
            int sameCount = 0;
            for(int j = 0; sameCount <= numRights[i] && j < len; ++j) {
                if((diff&1) == 0)
                    ++sameCount;
                diff >>= 1;
            }
            if((len < n && sameCount > numRights[i]) || (len == n && sameCount != numRights[i]))
                return true;
        }
        return false;
    }
    static final long[] ONES = new long[36];
    static {
        for(int i = 0; i <= 35; ++i)
            ONES[i] = (long) Math.pow(2, i);
    }

    static long solve() {       
        final long MAX = Long.parseLong("11111", 2);
        Set<Long> notViolates = new HashSet<Long>();
        for (long i = 0; i <= MAX; ++i) {
            if(!violates(i, 5)) {
                notViolates.add(Long.valueOf(i));
            }
        }
        for(int len = 6; len <= n; ++len) {
            Set<Long> newNotViolates = new HashSet<Long>();
            for(Long x : notViolates) {
                Long x0 = x;
                if(!violates(x0.longValue(), len)) {
                    newNotViolates.add(x0);
                }
                Long x1 = Long.valueOf(ONES[len - 1] | x);
                if(!violates(x1.longValue(), len)) {
                    newNotViolates.add(x1);
                }
            }
            notViolates = newNotViolates;
        }
        return notViolates.size();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        String[] s = in.readLine().split(" ");
