public class Solution
{
    public static void main(String args[]) throws IOException
    {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        HashMap<String, ArrayList<String>> map = new HashMap<>();

        String[] line = br.readLine().split(" ");
        int n = Integer.parseInt(line[0]);

        for(int i = 0; i < n; i++)
        {
            line = br.readLine().split(" ");
            line[0] = line[0].toLowerCase();
            line[2] = line[2].toLowerCase();

            if(map.containsKey(line[2]))
                map.get(line[2]).add(line[0]);
            else
            {
                ArrayList<String> list = new ArrayList<>();
                list.add(line[0]);
                map.put(line[2], list);
            }
        }
        System.out.println(dfs("polycarp", map));
    }

    static int dfs(String node, HashMap<String, ArrayList<String>> map)
    {
        if(!map.containsKey(node))
            return 1;
        int max = 0;
        ArrayList<String> list = map.get(node);
        for(String s : list)
            max = Math.max(max, dfs(s, map));
        return max + 1;
    }
}
